import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve, relative } from 'node:path';
const read = p => JSON.parse(readFileSync(p, 'utf8'));
const save = (p, v) => { writeFileSync(p, JSON.stringify(v, null, 2) + '\n'); return read(p); };

const projectRoot = resolve('input/artifacts/l08/demo project');
const launch = read(`${projectRoot}/.workforce/development-launch.json`);
const scripts = read(`${projectRoot}/package.json`).scripts;
const applicationDirectory = resolve(projectRoot, launch.applicationDirectory);
const registeredPaths = {
  applicationDirectory,
  applicationConfiguration: resolve(applicationDirectory, launch.applicationConfiguration),
  connectionScript: resolve(projectRoot, launch.connectionScript),
  proxyScript: resolve(projectRoot, launch.proxyScript),
  startScript: resolve(projectRoot, 'Start-Development.ps1')
};
for (const p of Object.values(registeredPaths)) {
  if (relative(projectRoot,p).startsWith('..')) throw new Error('Artifact path outside allowed root');
}
const l08 = save('output/l08-analysis.json', {
  registration: 'input/artifacts/l08/demo project/.workforce/development-launch.json',
  entry: {command:'npm start', cwd:projectRoot, start:scripts.start, aliases:Object.keys(scripts), aliasesMatch:Object.values(scripts).every(v=>v===scripts.start)},
  paths:Object.fromEntries(Object.entries(registeredPaths).map(([name,path])=>[name,{path,exists:existsSync(path)}])),
  hostOrigin:new URL(launch.applicationUrl).origin,
  browserOrigin:new URL(launch.browserUrl).origin,
  missing:Object.keys(registeredPaths).filter(k=>!existsSync(registeredPaths[k])),
  readyToInvoke:false,
  servicesStarted:false,
  action:'从项目原受管接入入口恢复登记的 proxy.mjs，并重新运行只读检查；本轮不启动服务。',
  gaps:['未验证连接脚本行为、代理上游及 TLS 信任','未验证宿主 /health/ready、Runtime、平台、统一认证和模型服务','未验证原用户登录与浏览器业务操作']
});

const samples=read('input/artifacts/l09/samples.json').samples;
const statistical=read('output/l09-sample-summary.json');
const groups=statistical.groups.map(g=>{
  const rows=samples.filter(s=>s.scenario===g.scenario&&s.phase===g.phase&&s.visibility===g.visibility);
  const successes=rows.filter(s=>s.outcome==='success').map(s=>s.ms);
  const all=rows.map(s=>s.ms);
  return {...g, failureCount:rows.filter(s=>s.outcome==='error'||s.outcome==='timeout').length,
    successMinMs:Math.min(...successes),successMaxMs:Math.max(...successes),
    successMeanMs:successes.reduce((a,b)=>a+b,0)/successes.length,
    allAttemptMeanMs:all.reduce((a,b)=>a+b,0)/all.length,
    p95Eligible:successes.length>=20};
});
const l09=save('output/l09-analysis.json',{
  total:samples.length,groups,
  conclusion:'前台 warm 有 1 次超时、前台 cold 超过两秒，均未满足预算；后台 warm 样本组通过，仅说明后台样本。',
  pageAcceptanceProven:false,
  gaps:['没有从点击到所需数据可见且可操作的计时边界或浏览器渲染证据','缺入口、版本、身份权限、数据量和网络条件，无法确认样本代表原用户页面','前台 warm 只有 19 个成功样本、cold 只有 1 个，不报告其 p95','后台样本不能替代前台用户体验'],
  next:'按相同入口、版本、身份、数据量和网络条件补采前台冷/热场景，保留超时和失败；关联浏览器、代理、宿主、Runtime 及下游时间线定位后复测。'
});

const task=read('input/artifacts/l10/task.json');
const history=read('input/artifacts/l10/history.json');
const current=history.records.map(x=>x.event).filter(e=>e.seq>task.committedBeforeInput);
const call=current.find(e=>e.type==='tool/call'&&e.data.name==='workforce_update_task');
const result=current.find(e=>e.type==='tool/result'&&e.data.message?.toolCallId===call?.data.callId);
const l10=save('output/l10-analysis.json',{
  taskId:task.id,currentStatus:task.status,currentAssignee:task.assigneeId,
  currentAssignmentVersion:task.assignmentVersion,oldExecutionAssignmentVersion:task.oldExecutionAssignmentVersion,
  boundary:task.committedBeforeInput,selectedSeq:current.map(e=>e.seq),
  excludedPriorCompletedSeq:history.records.map(x=>x.event).filter(e=>e.seq<=task.committedBeforeInput&&e.type==='turn/end').map(e=>e.seq),
  tool:{name:call.data.name,callId:call.data.callId,callSeq:call.seq,resultSeq:result.seq,isError:result.data.message.isError,errorCode:result.data.message.content[0].text},
  currentTurnCompleted:false,businessCompleted:false,
  interpretation:'旧 assignmentVersion=7 的 AI 在当前 paused、human-owner、version=8 的授权边界外尝试写回，被 task.execution_forbidden 拒绝；随后完成自述没有改变工具失败或任务状态。',
  actionsTaken:['只读解析原任务及 seq > 100 的持久事件','运行历史汇总器，确认 1 个失败工具调用，没有本轮 turn/end'],
  next:['保持 paused 和人工负责人，保留原会话及已撤销旧执行','由当前 human-owner 在原任务 UI 核对实际交付后维护进度；本轮不写状态','任务完成展示以当前任务持久状态及工具结果为依据，不能采用 AI 完成自述','后续如获准只读查询，应以同一 throughSeq/beforeSeq 补历史并核对原任务 execution-conversation；不恢复或重放旧执行'],
  gaps:['hasMore=true，历史并非完整快照','原材料没有 tenantId、userId、sessionId、executionId、throughSeq，完整身份与执行关联尚未证明','没有实际业务交付记录或原任务页面重新读取证据'],
  aiResumed:false,taskMutated:false
});

const receipt=read('input/artifacts/l11/receipt.json');
save('output/l11-normalized-receipt.json',{target:receipt.target,installation:receipt.installation,operation:receipt.operation});
save('output/l11-normalization.json',{
  source:'input/artifacts/l11/receipt.json',
  preservedFields:['target','installation','operation'],
  omittedComponentsReason:'原材料 components 只有数组，缺 installationId/tenantId/versionId/revision 回执信封；不补造关联字段。原数组仍保留于源文件。'
});
const checkArgs=['input/skills/xrain-app-operations/scripts/inspect-operation.mjs','output/l11-normalized-receipt.json'];
const checked=spawnSync(process.execPath,checkArgs,{encoding:'utf8'});
writeFileSync('output/l11-normalized-inspection.json',checked.stdout);
if(checked.stderr) writeFileSync('output/l11-normalized-inspection-stderr.txt',checked.stderr);
save('output/l11-normalized-inspection-command.json',{command:['node',...checkArgs],exitCode:checked.status});
const checkedJson=read('output/l11-normalized-inspection.json');
const l11=save('output/l11-analysis.json',{
  target:receipt.target,
  comparisons:{tenant:{expected:receipt.target.tenantId,observed:receipt.installation.tenantId,match:receipt.target.tenantId===receipt.installation.tenantId},operation:{expected:receipt.target.operationId,observed:receipt.operation.id,installationLatest:receipt.installation.latestOperationId,match:receipt.target.operationId===receipt.operation.id},package:{expected:receipt.target.packageId,observed:receipt.installation.packageId},version:{expected:receipt.target.versionId,observed:receipt.installation.installedVersionId}},
  inspection:checkedJson,
  conclusion:'不能宣布 tenant-lab 升级完成。成功 operation 属于 apo-unrelated，提供的安装记录属于 tenant-other；同包同版本不足以建立本次升级关联。',
  next:'仅在 tenant-lab 原授权会话重新取得 apg-11 安装记录、原 apo-11 operation、关联预检和带来源标识的组件回执，核对 installedVersionId、revision 与 active/latest 指针后再做用户验收。',
  mutations:false
});

const config=read('input/artifacts/l12/configuration.json');
const differences=Object.keys(config.definitions.current).filter(k=>config.definitions.current[k]!==config.session[k]).map(k=>({field:k,currentDefinition:config.definitions.current[k],originalSession:config.session[k]}));
const l12=save('output/l12-analysis.json',{
  discovered:config.skillDiscovered,loaded:config.skillLoaded,nativeTools:config.nativeTools,businessTools:config.businessTools,
  sameAgentId:config.definitions.current.agentId===config.session.agentId,
  differences,hostObservation:config.hostObservation,
  diagnosis:[
    {layer:'工具目录和员工工具策略',evidence:'skillDiscovered=true、skillLoaded=true，但 nativeTools=[]，仅有业务工具 task_read。',result:'skill 只提供说明，不会注册或授予命令工具；目前缺少获准的命令 schema/能力。',handling:'保留既有工具策略；需要命令诊断时交由原受管、已获准的执行入口处理，本轮不扩大 nativeTools。'},
    {layer:'定义到既有会话的配置应用',evidence:'同一 employee-fixed 当前定义为 workspace-new/preset-new/model-b；原 session-original 仍为 workspace-old/preset-old/model-a；宿主 configureDelegate=false，原因 immutable_workspace_or_preset。',result:'新定义未应用到旧会话，不能把目录中的新模型视为该会话已切换。',handling:'保留原会话；由原宿主检查会话模型目录及 /model 能力，若模型可独立更新才按后续授权通过原 UI 设置；workspace/preset 需要新会话时应明确限制，后续可选择新会话应用新定义，原历史继续保留。'}
  ],
  next:['核对原会话的实际工具 schema、授权与装配刷新机制','分别验证模型选择是否可独立更新以及 immutable workspace/preset 的宿主限制','任何后续验证须回到原问题，检查真实工具结果、持久业务结果和会话历史隔离'],
  gaps:['没有本轮模型请求记录，不能归因认证、配额或模型服务故障','离线接口未提供原会话 models/model 与工具 schema 查询，不能证明刷新或独立换模可行'],
  permissionsExpanded:false,sessionsDeleted:false,configurationMutated:false
});
console.log(JSON.stringify({l08:{readyToInvoke:l08.readyToInvoke,missing:l08.missing},l09:{total:l09.total,groups:l09.groups},l10:{status:l10.currentStatus,tool:l10.tool,businessCompleted:l10.businessCompleted},l11:l11.inspection,l12:{differences:l12.differences,nativeTools:l12.nativeTools,hostObservation:l12.hostObservation}},null,2));

