const roundtrip=read('output/answers.json');
const expected=Array.from({length:12},(_,i)=>`l${String(i+1).padStart(2,'0')}`);
const actual=roundtrip.answers.map(x=>x.id);
if(JSON.stringify(actual)!==JSON.stringify(expected)) throw new Error('Case coverage mismatch');
const catalogNames=new Set(read('input/catalog.json').map(x=>x.name));
for(const answer of roundtrip.answers){
  if(answer.skill!==null&&!catalogNames.has(answer.skill)) throw new Error('Unknown skill');
  for(const key of ['conclusion','actions','evidence','unresolved']) {
    if(key==='conclusion' ? typeof answer[key]!=='string' : !Array.isArray(answer[key])) throw new Error(`Invalid ${answer.id} ${key}`);
