perform-actions.mjs.content:
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { request } from './request.mjs';
const saved = (label) => JSON.parse(readFileSync(`output/${label}-response.json`, 'utf8')).data;
const requireSuccess = (r, label) => { if (r.status < 200 || r.status >= 300) throw new Error(`${label}: HTTP ${r.status}`); return r.data; };

const gateway = JSON.parse(readFileSync('input/artifacts/l01/binding-directory.json', 'utf8')).find(x => x.label === '订单测试网关');
if (!gateway) throw new Error('Requested binding missing');
const i1 = saved('l01-installation-before');
requireSuccess(request('l01-resolve', 'l01', 'POST', '/api/application/v1/operations/apo-1/resolve', {
  expectedRevision: i1.revision,
  tenantBindings: { 'apr-http/baseAddress': gateway.baseAddress },
  resolutions: { 'apr-view/Label': 'KeepTenant' }
}), 'l01-resolve');
request('l01-operation-after','l01','GET','/api/application/v1/operations/apo-1');
request('l01-installation-after','l01','GET','/api/application/v1/installations/api-1');
request('l01-components-after','l01','GET','/api/application/v1/installations/api-1/components');

const i2 = saved('l02-installation-before');
const o2 = saved('l02-operation-before');
if (i2.revision !== o2.sourceRevision || o2.status !== 'Failed') throw new Error('l02 state changed');
const retried = requireSuccess(request('l02-retry','l02','POST','/api/application/v1/operations/apo-2/retry',{
  requestId: `l02-retry-${randomUUID()}`, expectedRevision: i2.revision
}), 'l02-retry');
if (!retried.id || retried.id === o2.id) throw new Error('l02 retry must have a new operation');
request('l02-operation-after','l02','GET',`/api/application/v1/operations/${retried.id}`);
request('l02-original-after','l02','GET','/api/application/v1/operations/apo-2');
request('l02-installation-after','l02','GET','/api/application/v1/installations/api-2');
request('l02-components-after','l02','GET','/api/application/v1/installations/api-2/components');

requireSuccess(request('l03-continue','l03','POST','/api/application/v1/operations/apo-3/continue',{}),'l03-continue');
request('l03-operation-after','l03','GET','/api/application/v1/operations/apo-3');
request('l03-installation-after','l03','GET','/api/application/v1/installations/api-3');
request('l03-components-after','l03','GET','/api/application/v1/installations/api-3/components');

requireSuccess(request('l04-restore','l04','POST','/api/application/v1/installations/api-4/components/apr-view:restore',{
  expectedRevision: saved('l04-installation-before').revision
}),'l04-restore');
request('l04-installation-after','l04','GET','/api/application/v1/installations/api-4');
request('l04-components-after','l04','GET','/api/application/v1/installations/api-4/components');

const uninstalled = requireSuccess(request('l05-uninstall','l05','DELETE','/api/application/v1/installations/api-5',{
  requestId: `l05-uninstall-${randomUUID()}`, expectedRevision: saved('l05-installation-before').revision
}),'l05-uninstall');
if (!uninstalled.id) throw new Error('l05 missing operation ID');
request('l05-operation-after','l05','GET',`/api/application/v1/operations/${uninstalled.id}`);
request('l05-installation-after','l05','GET','/api/application/v1/installations/api-5');
request('l05-components-after','l05','GET','/api/application/v1/installations/api-5/components');

requireSuccess(request('l06-grant-read','l06','PUT','/api/xrain/v1/applications/app-orders/execution-authorization/grants',{
  permissionIds: ['perm-orders-read']
}),'l06-grant-read');
request('l06-authorization-after','l06','GET','/api/xrain/v1/applications/app-orders/execution-authorization');

let scope = saved('l07-publication-before');
let completed = false;
for (let attempt = 1; attempt <= 3; attempt++) {
  const response = request(`l07-publication-update-${attempt}`,'l07','PUT','/api/xrain/v1/applications/app-sales/publication-scope',{
    mode: scope.mode,
    userIds: [...new Set([...scope.userIds,'user-li'])],
    departments: scope.departments,
    expectedRevision: scope.revision
  });
  if (response.status >= 200 && response.status < 300) { completed = true; break; }
  if (response.status !== 409) throw new Error(`l07 unexpected HTTP ${response.status}`);
  scope = requireSuccess(request(`l07-publication-conflict-read-${attempt}`,'l07','GET','/api/xrain/v1/applications/app-sales/publication-scope'),'l07 conflict read');
}
if (!completed) throw new Error('l07 concurrency retries exhausted');
request('l07-publication-after','l07','GET','/api/xrain/v1/applications/app-sales/publication-scope');

