request.mjs.content:
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function request(label, caseId, method, apiPath, body) {
  if (!/^l\d{2}-[a-z0-9-]+$/.test(label)) throw new Error('Invalid evidence label');
  const args = ['input/lab.mjs', 'request', caseId, method, apiPath];
  if (body !== undefined) {
    const bodyPath = `output/${label}-body.json`;
    writeFileSync(bodyPath, JSON.stringify(body, null, 2) + '\n');
    args.push(bodyPath);
  }
  writeFileSync(`output/${label}-request.json`, JSON.stringify({ caseId, method, apiPath, body, command: ['node', ...args], nodeVersion: process.version }, null, 2) + '\n');
  const result = spawnSync(process.execPath, args, { encoding: 'utf8' });
  writeFileSync(`output/${label}-response.json`, result.stdout || '');
  if (result.stderr) writeFileSync(`output/${label}-stderr.txt`, result.stderr);
  const savedResponse = readFileSync(`output/${label}-response.json`, 'utf8');
  let response;
  try { response = JSON.parse(savedResponse); }
  catch { throw new Error(`Response parse failed for ${label}: exit ${result.status}`); }
  console.log(JSON.stringify({ label, ...response }));
  if (result.error) throw result.error;
  return response;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [label, caseId, method, apiPath, bodyFile] = process.argv.slice(2);
  request(label, caseId, method, apiPath, bodyFile ? JSON.parse(readFileSync(bodyFile, 'utf8')) : undefined);
}

