import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const checks = [
  ['l08-launch-inspection','input/skills/workforce-runtime/scripts/inspect-launch.mjs','input/artifacts/l08/demo project'],
  ['l09-sample-summary','input/skills/workforce-runtime/scripts/summarize.mjs','input/artifacts/l09/samples.json'],
  ['l10-history-summary','input/skills/workforce-agent-troubleshoot/scripts/summarize-history.mjs','input/artifacts/l10/history.json','--after-seq','100'],
  ['l11-receipt-inspection','input/skills/xrain-app-operations/scripts/inspect-operation.mjs','input/artifacts/l11/receipt.json']
];
for (const [label, ...args] of checks) {
  const result = spawnSync(process.execPath, args, {encoding:'utf8'});
  writeFileSync(`output/${label}-command.json`,JSON.stringify({command:['node',...args],exitCode:result.status,nodeVersion:process.version},null,2)+'\n');
  writeFileSync(`output/${label}.json`,result.stdout || '');
  if(result.stderr) writeFileSync(`output/${label}-stderr.txt`,result.stderr);
  const parsed=JSON.parse(readFileSync(`output/${label}.json`,'utf8'));
  console.log(JSON.stringify({label,exitCode:result.status,result:parsed}));
}

